<template>
  <div class="login-page login-page--register">
    <div class="login-bg" aria-hidden="true" />
    <div v-if="bgSrc" class="bg-photo" aria-hidden="true">
      <img class="bg-photo__img" :src="bgSrc" alt="" />
      <div class="bg-photo__scrim" />
    </div>

    <div class="content content--register">
      <header class="header">
        <h1 class="title">Create account</h1>
        <p class="subtitle">
          Already have an account?
          <button type="button" class="link-inline" @click="goLogin">
            Log in
          </button>
        </p>
      </header>

      <div class="field">
        <label class="label" for="reg-name">Your name</label>
        <input
          id="reg-name"
          v-model="name"
          class="input"
          type="text"
          autocomplete="name"
        />
      </div>

      <div class="field">
        <label class="label" for="reg-email">Your email address</label>
        <input
          id="reg-email"
          v-model="email"
          class="input"
          type="email"
          autocomplete="email"
        />
      </div>

      <div class="field">
        <label class="label" for="reg-password">Your password</label>
        <div class="password-wrap">
          <input
            id="reg-password"
            v-model="password"
            class="input input-password"
            :type="showPassword ? 'text' : 'password'"
            autocomplete="new-password"
          />
          <button
            type="button"
            class="eye-btn"
            :aria-label="showPassword ? 'Hide password' : 'Show password'"
            @click="showPassword = !showPassword"
          >
            <span class="material-icons eye-icon">{{
              showPassword ? 'visibility' : 'visibility_off'
            }}</span>
          </button>
        </div>
      </div>

      <div class="field">
        <label class="label" for="reg-password-confirm">Confirm your password</label>
        <div class="password-wrap">
          <input
            id="reg-password-confirm"
            v-model="passwordConfirmation"
            class="input input-password"
            :type="showPasswordConfirmation ? 'text' : 'password'"
            autocomplete="new-password"
          />
          <button
            type="button"
            class="eye-btn"
            :aria-label="
              showPasswordConfirmation ? 'Hide password' : 'Show password'
            "
            @click="showPasswordConfirmation = !showPasswordConfirmation"
          >
            <span class="material-icons eye-icon">{{
              showPasswordConfirmation ? 'visibility' : 'visibility_off'
            }}</span>
          </button>
        </div>
      </div>

      <div class="field">
        <label class="label" for="reg-mobile">Your mobile number</label>
        <input
          id="reg-mobile"
          v-model="mobile"
          class="input"
          type="tel"
          autocomplete="tel"
        />
      </div>

      <div class="field">
        <label class="label" for="reg-address">House address (optional)</label>
        <input
          id="reg-address"
          v-model="houseAddress"
          class="input"
          type="text"
          autocomplete="street-address"
        />
      </div>

      <div class="field">
        <label class="label" for="reg-postcode">Postcode (optional)</label>
        <input
          id="reg-postcode"
          v-model="postcode"
          class="input"
          type="text"
          autocomplete="postal-code"
        />
      </div>

      <div class="field field--delivery">
        <p class="label label--static">Delivery type (optional)</p>
        <div class="delivery-type-buttons">
          <button
            v-for="type in deliveryTypes"
            :key="type"
            type="button"
            class="delivery-type-button"
            :class="{ 'delivery-type-button--active': deliveryType === type }"
            @click="toggleDeliveryType(type)"
          >
            {{ type }}
          </button>
        </div>
      </div>

      <button
        type="button"
        class="btn-primary"
        :class="{ 'btn-primary--disabled': isLoading }"
        :disabled="isLoading"
        @click="handleRegister"
      >
        <span v-if="isLoading" class="btn-spinner" />
        <span v-else>Register</span>
      </button>
    </div>

    <footer class="footer">{{ versionLabel }}</footer>
  </div>
</template>

<script>
import { mapActions } from 'vuex';
import pkg from '../../package.json';
import { DELIVERY_TYPES } from '../utils/constants';

export default {
  name: 'RegisterView',
  data() {
    return {
      name: '',
      email: '',
      password: '',
      passwordConfirmation: '',
      showPassword: false,
      showPasswordConfirmation: false,
      mobile: '',
      houseAddress: '',
      postcode: '',
      deliveryType: '',
      isLoading: false,
      deliveryTypes: [...DELIVERY_TYPES],
      bgSrc: require('../assets/login-bg-top-right.png'),
      versionLabel: `${pkg.version} (v217)`,
    };
  },
  methods: {
    ...mapActions('auth', ['register']),
    toggleDeliveryType(type) {
      this.deliveryType = this.deliveryType === type ? '' : type;
    },
    async handleRegister() {
      if (!this.name.trim()) {
        window.alert('Please enter your name');
        return;
      }
      if (!this.email.trim()) {
        window.alert('Please enter your email');
        return;
      }
      if (!this.password || this.password.length < 8) {
        window.alert('Password must be at least 8 characters');
        return;
      }
      if (this.password !== this.passwordConfirmation) {
        window.alert('Passwords do not match');
        return;
      }
      if (!this.mobile.trim()) {
        window.alert('Please enter your mobile number');
        return;
      }

      this.isLoading = true;
      try {
        await this.register({
          name: this.name.trim(),
          email: this.email.trim().toLowerCase(),
          password: this.password,
          password_confirmation: this.passwordConfirmation,
          mobile: this.mobile.trim(),
          house_address: this.houseAddress.trim() || undefined,
          postcode: this.postcode.trim() || undefined,
          delivery_type: this.deliveryType || undefined,
        });
        window.alert(
          'Registration successful! Please wait for admin confirmation.'
        );
        this.$router.replace({ name: 'DriverHome' });
      } catch (error) {
        window.alert(error.message || 'Please try again');
      } finally {
        this.isLoading = false;
      }
    },
    goLogin() {
      this.$router.push({ name: 'Login' });
    },
  },
};
</script>

